INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-A-001', 'S', 'lrp', 'A', '{"title":"Library volunteer","scenario":"You are a new volunteer at a college library. A librarian is showing you how to help visitors.","sentences":["Please welcome visitors at the front desk.","Show them where the quiet study rooms are.","Visitors with a student card can borrow up to five books.","If a book is late, please ask the visitor to pay a fee.","The printers on the second floor are free for all students.","Anyone looking for old newspapers should ask the basement librarian.","Remind everyone to return their books before the library closes."],"syl":[10,10,15,15,14,18,17]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-A-002', 'S', 'lrp', 'A', '{"title":"Campus café trainee","scenario":"You are a new worker at the campus café. The manager is explaining the rules of the job.","sentences":["Always wash your hands before starting work.","Greet every customer with a smile.","Write each order clearly on a card and give it to the cook.","Please keep the counter clean and put the cups back on the shelf.","If a customer has an allergy, ask the manager first.","The coffee machine must be turned off and cleaned at the end of every evening.","On busy days, you can take a short break after you finish the lunch rush."],"syl":[10,11,15,14,16,21,18]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-A-003', 'S', 'lrp', 'A', '{"title":"Dormitory helper","scenario":"You are a student helper at a dormitory. A resident advisor is training you to welcome new students.","sentences":["Give each new student a key and a folder.","Show them where the laundry room is located.","Remind them that visitors must leave the building by ten o''clock.","The kitchen on each floor is shared by all of the residents.","If students lose their keys, they should contact the front office right away.","Please tell them that the heating in every room can be controlled with the small dial.","Students who need help with their luggage can ask a volunteer wearing a green badge."],"syl":[11,10,16,15,17,20,20]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-A-004', 'S', 'lrp', 'A', '{"title":"Laboratory safety","scenario":"You are assisting in a chemistry laboratory. A teaching assistant is explaining the safety rules.","sentences":["Always wear your safety glasses in the lab.","Tie back your hair before you begin.","Never taste or smell any of the chemicals in the lab.","If something spills, tell your instructor and leave the area.","Put used glass into the special box, not into the trash.","After class, wash your hands and return all equipment to the correct shelf.","Students who have long sleeves should roll them up so they do not touch the burners."],"syl":[11,9,14,15,14,18,18]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-005', 'S', 'lrp', 'B', '{"title":"Science museum guide","scenario":"You are a volunteer guide at a college science museum. A coordinator is training you to talk to visitors.","sentences":["Welcome the visitors to the museum.","Explain how to use the exhibits.","The dinosaur exhibit is located on the second floor.","Young children must always be accompanied by an adult.","Please ask visitors not to touch the fragile glass cases.","The gift shop near the exit sells books, posters, and small science kits for children.","If you cannot answer a question, politely suggest asking a staff member."],"syl":[10,9,15,15,14,18,21]}', NULL, NULL, NULL, 0, 'pretest', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-006', 'S', 'lrp', 'B', '{"title":"International student ambassador","scenario":"You are a student ambassador at the international office. A staff member is training you to give advice to new students.","sentences":["Check your university email daily.","Bring your passport and visa to the office.","The campus bank offers special accounts for new students.","Students can join a conversation group to practice speaking English.","If you have questions about classes, visit your advisor.","You must register for all of your courses online before the first week ends.","Many students visit the writing center, where tutors review their essays."],"syl":[11,11,14,17,14,18,19]}', NULL, NULL, NULL, 0, 'pretest', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-007', 'S', 'lrp', 'B', '{"title":"Psychology survey assistant","scenario":"You are a student assistant in a psychology department. A professor is explaining how to run a short survey.","sentences":["Please greet each participant politely.","Explain that the survey is voluntary.","Participants should sign a consent form before the survey begins.","The questionnaire takes about fifteen minutes to complete.","If someone feels uncomfortable, they may stop at any time.","After each session, thank the participant and write the date in the notebook.","Please keep all the finished answer sheets in the locked cabinet every evening."],"syl":[11,11,17,14,15,20,21]}', NULL, NULL, NULL, 0, 'pretest', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-008', 'S', 'lrp', 'B', '{"title":"Campus tour guide","scenario":"You are leading a campus tour for prospective students. A tour manager is reviewing what to say at each stop.","sentences":["Begin by introducing yourself.","The library is open until midnight.","The science building has modern laboratories for students.","Most first-year students live in the residence halls near the sports center.","Lunch is served in the dining hall from eleven thirty until two.","Students can join one of over a hundred clubs that meet in the union.","Questions about applying can be sent to the admissions office directly."],"syl":[9,11,15,17,17,17,19]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-C-009', 'S', 'lrp', 'C', '{"title":"Conference volunteer","scenario":"You are volunteering at an academic conference. The organizer is explaining your responsibilities.","sentences":["Please check each guest''s name badge carefully.","Direct guests to the registration desk.","Speakers must arrive early to test their presentation equipment.","Lunch is provided for registered participants only.","The poster session takes place in the east wing of the building.","Anyone having difficulty hearing should be directed to the front seats.","If a technical problem occurs, tell the coordinator right away."],"syl":[10,10,17,14,15,18,18]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-C-010', 'S', 'lrp', 'C', '{"title":"Student newspaper intern","scenario":"You are an intern at the student newspaper. An editor is explaining how to prepare for an interview.","sentences":["Research your subject thoroughly beforehand.","Prepare questions that need detailed answers.","Always ask permission before recording a conversation.","Listen closely, since good questions often follow answers.","Take notes by hand as well, in case the recording does not work.","Afterward, send a brief message to thank the person and confirm the quotations.","Every claim in an article should be supported by a reliable source."],"syl":[12,10,16,15,15,20,19]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-C-011', 'S', 'lrp', 'C', '{"title":"Water-testing project","scenario":"You are a research assistant in an environmental science laboratory. A professor is describing a water-testing project.","sentences":["We collect samples from the river weekly.","Label each bottle with the date and place.","The samples must be kept cold until they reach the laboratory.","Measure the temperature and acidity of the water first.","Record each measurement carefully in your field notebook.","Because the instruments are sensitive, carry them in the protective case.","If the readings differ greatly from last week''s results, repeat the test again."],"syl":[11,10,17,17,17,19,19]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-C-012', 'S', 'lrp', 'C', '{"title":"Teaching assistant duties","scenario":"You are a teaching assistant for an introductory economics course. The instructor is explaining your duties.","sentences":["Please arrive ten minutes before class.","Hand out the problem sets at the door.","Students often ask what the final exam will cover.","Direct those questions to me instead of answering them yourself.","Weekly tutorials are held on Tuesday and Thursday afternoons.","Please explain to students that late assignments lose ten percent for each day.","At the end of the semester, you will help organize the final projects."],"syl":[9,9,14,16,16,18,19]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-013', 'S', 'lrp', 'B', '{"title":"Recycling center","scenario":"You are helping at the campus recycling center. The supervisor is explaining how to sort items for incoming students.","sentences":["Please sort the plastic bottles by color.","Paper goes into the blue containers.","Cardboard boxes should be flattened before they go in the bin.","Glass containers need to be rinsed and placed on the top shelf.","If you are unsure about an item, ask the supervisor.","Batteries and other electronic devices should go to the front desk.","Before you leave, please make sure each container is empty and the lid is closed."],"syl":[10,10,14,14,16,18,19]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-014', 'S', 'lrp', 'B', '{"title":"IT help desk","scenario":"You have a part-time job at the campus IT help desk. A supervisor is training you to assist students with common problems.","sentences":["Greet each student and ask for a name.","Check whether the printer has paper.","Most wireless problems can be fixed by restarting the router.","Students who forget their passwords must show a valid student card.","If a laptop will not turn on, plug it in for ten minutes first.","Please tell students that the library lends tablets and chargers for up to three days.","At closing time, record every repair in the log and lock the cabinet."],"syl":[9,9,16,16,16,20,20]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-015', 'S', 'lrp', 'B', '{"title":"Career fair volunteer","scenario":"You are volunteering at a university career fair. A coordinator is explaining how to welcome employers and students.","sentences":["Welcome each employer at the entrance.","Give every visitor a name tag.","Employers are seated at tables arranged by industry.","Please direct students to the resume workshop in the small hall.","If a representative needs water, bring it to their table.","Students should bring several copies of their resumes and a list of questions.","When the fair closes, help the employers pack up their displays carefully."],"syl":[10,10,14,15,16,19,18]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-016', 'S', 'lrp', 'B', '{"title":"Fitness center desk","scenario":"You are working at the front desk of the campus fitness center. The manager is describing your responsibilities.","sentences":["Scan each student''s card at the door.","Towels are available near the lockers.","Group classes fill up quickly, so students should reserve a spot online.","Visitors must pay a small fee unless a member brings them.","Please remind everyone to wipe the machines after using them.","If you notice any damaged equipment, put a sign on it and tell me.","The pool closes for cleaning every Wednesday, so please empty your locker by noon."],"syl":[8,11,16,15,16,18,21]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-017', 'S', 'lrp', 'B', '{"title":"Campus radio station","scenario":"You are a new volunteer at the campus radio station. A student manager is showing you how the studio works.","sentences":["Turn on the microphone before you speak.","Keep your headphones on during the show.","Each program begins with a short introduction and the news.","Please choose music that is appropriate for all listeners.","If a guest arrives early, offer them a seat in the lounge.","Never open the studio door while the red light above it is shining.","After your show, save the recording and write the song list on the schedule board."],"syl":[10,9,15,14,15,19,20]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-018', 'S', 'lrp', 'B', '{"title":"Campus bookstore","scenario":"You are working at the campus bookstore at the start of the semester. The manager is explaining how to help customers.","sentences":["Ask students which courses they are taking.","Used books are cheaper than new ones.","Textbooks can be returned within two weeks with a receipt.","Please restock the popular titles every morning.","Students can sell their old books back at the counter near the entrance.","Customers who want a discount should show a student card before they pay.","If a book is out of stock, take the customer''s email so the store can order it."],"syl":[9,8,14,14,16,18,21]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-019', 'S', 'lrp', 'B', '{"title":"Community garden","scenario":"You are volunteering at a community garden run by the university. The garden leader is explaining the weekly tasks.","sentences":["Water the plants early in the morning.","Pull out the weeds around the tomatoes.","Vegetables are picked on Fridays and shared with families.","Please wear gloves and a hat when you work outside in the sun.","Please return all of the tools to the shed before you leave.","New volunteers should ask a leader before they plant anything in the empty beds.","During the summer, the garden hosts workshops where neighbors learn how to grow their own food."],"syl":[10,10,15,14,14,21,21]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-B-020', 'S', 'lrp', 'B', '{"title":"Admissions office intern","scenario":"You are an intern in the university admissions office. A staff member is explaining how to answer questions from applicants.","sentences":["Greet visitors with a friendly smile.","Applications are due by the first of March.","Please explain that all documents must be sent together.","Applicants can check their status on the university website.","If someone asks about scholarships, give them the information sheet.","International applicants must also submit proof of their English test scores.","Students who want to visit the campus can sign up for a guided tour at the front desk."],"syl":[10,11,14,17,17,20,21]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-A-021', 'S', 'lrp', 'A', '{"title":"Bike rental shop","scenario":"You are a new worker at a bike rental shop near campus. The owner is explaining your daily tasks.","sentences":["Please check each bike before you rent it.","Ask each customer to wear a helmet.","Write the customer''s name and phone number clearly on the form.","All bikes must be back at the shop before six in the evening.","If a tire is flat, please tell the repair person right away.","Tourists often ask about the best paths, so please learn the map of the lake.","At the end of each day, please wash all the bikes and put them in the back room."],"syl":[9,10,15,16,15,18,18]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-A-022', 'S', 'lrp', 'A', '{"title":"Health center desk","scenario":"You are a student helper at the campus health center. The nurse is explaining how to welcome patients.","sentences":["Please greet each student politely.","Ask for the name of the student first.","Check the appointment book and find the correct time for each student.","Students with a fever should sit in the small waiting room.","The nurse can see two students at the same time on busy days.","If a student feels very sick, call the nurse and bring a chair immediately.","Please keep the front desk tidy and answer the telephone before the third ring."],"syl":[9,9,16,14,15,20,19]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-A-023', 'S', 'lrp', 'A', '{"title":"Swimming pool assistant","scenario":"You are a part-time assistant at the campus swimming pool. The lifeguard is explaining the safety rules.","sentences":["Please walk slowly around the pool.","All children must wear a swimming cap.","Check that the pool gate is closed every hour of the day.","Swimmers should take a shower before they enter the water.","If you see a problem, blow the whistle and call the lifeguard.","The pool is closed on Sunday, so we clean the floor and test the water that day.","Please remind everyone that food and glass bottles are not allowed near the pool."],"syl":[8,9,14,15,16,19,19]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-A-024', 'S', 'lrp', 'A', '{"title":"Computer lab helper","scenario":"You are a student helper in the computer lab. A teacher is explaining what you should do each day.","sentences":["Please turn on all of the computers.","Sign each student into the lab book.","Show new students how to log in to the system on the first day.","Students can print up to ten pages for free every week.","If a computer is not working, put a red card on the screen.","The lab is quiet during exam week, so please ask students to speak softly.","Before you leave in the evening, turn off the lights and lock the door."],"syl":[9,9,16,14,16,19,17]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-C-025', 'S', 'lrp', 'C', '{"title":"Museum exhibit assistant","scenario":"You are an assistant at a university art museum. The curator is describing how new exhibits are prepared.","sentences":["Handle every artifact with great care.","Record the condition of each piece.","Visitors are not permitted to touch any of the displays.","Lighting must be adjusted to protect the older paintings.","Please document each loan before the exhibit opens.","Before each opening, we review the catalog to confirm the descriptions.","Report any damage to the registrar at once, even if it seems minor."],"syl":[11,9,14,14,14,20,19]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-C-026', 'S', 'lrp', 'C', '{"title":"Orientation week coordinator","scenario":"You are helping to organize orientation week for new international students. The coordinator is explaining your responsibilities.","sentences":["Distribute the welcome packets at the door.","Introduce yourself to each newcomer.","Students who need housing assistance should visit the second table.","Please make sure that every group leader has a complete schedule.","Questions about visas go to the international office.","Some students will feel nervous, so try to be patient and encouraging at all times.","After the closing session, collect the feedback forms and return them to my office."],"syl":[11,10,17,17,16,21,21]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-C-027', 'S', 'lrp', 'C', '{"title":"Field research assistant","scenario":"You are assisting a professor with a field study of local birds. The professor is explaining the procedures.","sentences":["Arrive at the site before sunrise.","Record the weather conditions carefully.","Binoculars should be returned to the equipment case afterward.","Please avoid making sudden noises near the nesting areas.","Each sighting must be entered into the data sheet without delay.","If you are unsure about a species, take a photograph instead of guessing.","We will compare this season''s results with last year''s at our weekly meeting."],"syl":[9,12,17,14,17,20,18]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-C-028', 'S', 'lrp', 'C', '{"title":"Alumni event planner","scenario":"You are an intern in the university alumni office. Your supervisor is explaining how to prepare for the annual reunion.","sentences":["Confirm the guest list with the registration team.","Contact the caterer about special diets.","Name tags should be printed in advance for every attendee.","Please reserve the main auditorium for the keynote speaker.","Our budget does not allow extra decorations this year.","On the day, you will be responsible for greeting the former students warmly.","After the reunion, we will send a survey to see how we can improve."],"syl":[12,11,15,15,15,20,18]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-A-029', 'S', 'lrp', 'A', '{"title":"Parking office helper","scenario":"You are a student helper at the campus parking office. The manager is explaining the daily rules.","sentences":["Please greet every driver politely.","Check the permit on the window.","Visitors can park only in the blue area near the gate.","Drivers must pay at the machine before they leave the lot.","If a car blocks the road, call the security office.","The north parking lot is full by eight, so please send new drivers to the east lot.","At the end of the shift, write the number of cars on the report sheet."],"syl":[11,8,15,14,14,19,17]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-A-030', 'S', 'lrp', 'A', '{"title":"Cafeteria cashier","scenario":"You are a new cashier in the student cafeteria. The supervisor is explaining your tasks.","sentences":["Please count the money in the morning.","Smile and say hello to everyone.","Students can pay with cash or with their meal card at any counter.","Always give the customer a receipt after the payment.","If the line is long, ask another worker to help you.","The price of the soup changes every day, so check the sign near the register.","Before you go home, put the money in the box and give the key to the manager."],"syl":[9,10,15,15,14,19,21]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-A-031', 'S', 'lrp', 'A', '{"title":"Language lab assistant","scenario":"You are an assistant in the language lab. The teacher is explaining how to help the students.","sentences":["Please open the lab at nine o''clock.","Give each student a pair of headphones.","Show the students where the practice lessons are on the computer.","Visitors must write their names on the list at the door.","If the sound is not working, try another computer first.","Students can borrow a dictionary, but they must return it before closing.","When the last class is over, collect the headphones and lock them in the cabinet."],"syl":[9,9,16,13,15,20,20]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-A-032', 'S', 'lrp', 'A', '{"title":"Dormitory front desk","scenario":"You are working at the front desk of a student dormitory. The manager is describing your duties.","sentences":["Please check the name of every guest.","Keep all of the keys in the small box.","Residents may invite only one friend at a time.","Guests must leave the building before eleven at night.","If a package arrives, put a note on the resident''s door.","The laundry room is open all day, but the machines stop working at midnight.","Please tell the residents about the fire drill, which will be on Friday afternoon."],"syl":[9,9,13,13,15,19,20]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-C-033', 'S', 'lrp', 'C', '{"title":"Debate tournament volunteer","scenario":"You are volunteering at a university debate tournament. The organizer is explaining your responsibilities.","sentences":["Escort each team to its assigned room.","Distribute the judging forms promptly.","Competitors should arrive at least fifteen minutes before each round.","Please keep the corridors quiet while the debates are in progress.","Every timekeeper must be seated before the first speech begins.","If a judge is absent, tell the head organizer so we can find another.","After the final round, collect the scoring sheets and give them to the director."],"syl":[9,9,17,17,17,20,20]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-C-034', 'S', 'lrp', 'C', '{"title":"Archive assistant","scenario":"You are an assistant in the university library archive. The archivist is explaining the procedures.","sentences":["Wash your hands before touching documents.","Use only pencils instead of ink pens.","Visitors must request materials at least a day in advance.","Photographs are allowed only with the archivist''s permission.","Fragile letters should be handled with extreme gentleness.","Every item that leaves the reading room must be recorded in the logbook.","If you notice moisture, tell me so that we can protect the collection."],"syl":[10,10,16,16,14,19,18]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-C-035', 'S', 'lrp', 'C', '{"title":"Peer tutoring coordinator","scenario":"You are a coordinator in the peer tutoring program. The program director is explaining your duties.","sentences":["Match each student with a suitable tutor.","Confirm all sessions by email.","Tutors are expected to prepare materials in advance.","Please remind students to bring their assignments to each meeting.","Complaints should be reported to the director without delay.","Each month, you will summarize the attendance records in a short report.","Because demand increases before exams, we may need to recruit more tutors."],"syl":[11,8,14,15,15,18,19]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-LRP-C-036', 'S', 'lrp', 'C', '{"title":"Guest lecturer host","scenario":"You are a student host for a visiting professor. The department secretary is explaining how to welcome the speaker.","sentences":["Meet the professor at the main entrance.","Offer to carry her luggage.","Escort her to the faculty lounge for refreshments.","Please check that the projector is working properly.","Introduce yourself and explain the schedule for the afternoon.","During the lecture, you should sit near the front in case she needs any assistance.","Afterward, take her to the hotel and confirm her flight for tomorrow."],"syl":[10,8,13,13,17,19,18]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-001', 'S', 'int', 'A', '{"title":"Study habits","scenario":"A university is doing a survey about how students study. You will answer four questions from a researcher.","questions":["Where do you usually study, and why do you prefer that place?","What kinds of things distract you when you try to study?","Some people think students learn better in groups. What do you think?","How do you think studying will change in the next ten years?"]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-002', 'S', 'int', 'A', '{"title":"Free time","scenario":"A student magazine is asking readers about free time. You will answer four questions from a reporter.","questions":["What do you usually do on your days off?","Tell me about a hobby that you started recently or would like to start.","Do you think young people today have enough free time? Why or why not?","If you suddenly had a free month, how would you spend it?"]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-003', 'S', 'int', 'A', '{"title":"Food on campus","scenario":"A university is asking students about the food on campus. You will answer four questions from a researcher.","questions":["What do you usually eat for lunch on a school day?","How do you decide where to eat when you have a short break?","Some universities want to offer only healthy food. Do you think that is a good idea?","How might food on campuses change in the future?"]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-004', 'S', 'int', 'A', '{"title":"Getting around the city","scenario":"A city office is studying how people travel. You will answer four questions from a researcher.","questions":["How do you usually travel to school or work?","Tell me about a time when your trip took longer than you expected.","Many cities want people to use bicycles more. What do you think about this?","If your city could change one thing about its transportation, what should it be?"]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-005', 'S', 'int', 'A', '{"title":"Friends and communication","scenario":"A university research group is studying how young people stay in touch. You will answer four questions from a researcher.","questions":["How do you usually keep in touch with your friends?","Do you prefer to send messages or to talk on the phone? Why?","Some people say that technology makes friendships weaker. What is your opinion?","How do you think people will communicate with each other in twenty years?"]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-006', 'S', 'int', 'B', '{"title":"Learning languages","scenario":"A university is doing a study on language learning. You will answer four questions from a researcher.","questions":["Tell me about a language you have studied and how you began learning it.","What is the most helpful method you have found for improving your speaking?","Some people believe that apps will soon replace language teachers. Do you agree?","Imagine that everyone in the world spoke one common language. What would be the advantages and disadvantages?"]}', NULL, NULL, NULL, 0, 'pretest', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-007', 'S', 'int', 'B', '{"title":"Work and study","scenario":"A scholarship committee is interviewing students about working while studying. You will answer four questions.","questions":["Have you ever had a job or volunteer position while you were studying? Please describe it.","What skills do you think students can learn from working that they cannot learn in class?","Some universities limit how many hours students can work. Do you think this is a good rule?","If you were advising a first-year student, would you recommend working during the first semester? Why?"]}', NULL, NULL, NULL, 0, 'pretest', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-008', 'S', 'int', 'B', '{"title":"Choosing a major","scenario":"The career center is collecting students'' views on choosing a field of study. You will answer four questions from an adviser.","questions":["How did you decide what to study, or how do you plan to decide?","What do you think is the most important thing to consider when choosing a career?","Many people change their major at least once. Is that a positive or negative thing, in your view?","How might the jobs available to graduates be different in the future?"]}', NULL, NULL, NULL, 0, 'pretest', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-009', 'S', 'int', 'B', '{"title":"Sleep and schedules","scenario":"A university health project is studying student schedules. You will answer four questions from a researcher.","questions":["Describe your typical daily schedule during a busy week.","What do you do to stay focused when you are tired?","Some schools are moving the start of the day later to give students more sleep. What do you think of this idea?","If you could design the perfect schedule for students, what would it include?"]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-010', 'S', 'int', 'B', '{"title":"Public spaces","scenario":"A planning department is asking residents about public spaces in the city. You will answer four questions from a researcher.","questions":["Tell me about a public place in your city that you enjoy visiting.","What makes a public space comfortable for people to spend time in?","Some cities are replacing parking areas with parks. Do you think this is a good idea?","How do you think public spaces will change as more people work from home?"]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-011', 'S', 'int', 'C', '{"title":"Social media","scenario":"A university is researching the effects of social media. You will answer four questions from a researcher.","questions":["Which social media platforms do you use most, and how do you use them?","In what ways has social media changed the way you get information?","Some researchers say social media reduces people''s attention span. To what extent do you agree?","If governments were to regulate social media more strictly, what effects might this have?"]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-012', 'S', 'int', 'C', '{"title":"Environmental habits","scenario":"An environmental group is interviewing students about daily habits. You will answer four questions from an interviewer.","questions":["What have you done in your daily life to reduce waste?","What do you think prevents people from adopting more environmentally friendly habits?","Some people argue that individual actions matter little compared with the actions of companies. What is your view?","Suppose your city offered rewards for people who reduce their waste. How effective do you think this would be?"]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-013', 'S', 'int', 'C', '{"title":"Decision-making","scenario":"A psychology department is studying how people make decisions. You will answer four questions from a researcher.","questions":["Tell me about an important decision you made recently.","When you have to make a difficult decision, do you prefer to rely on advice or on your own judgment? Why?","Some people claim that having too many choices makes decisions harder. Do you agree?","How might artificial intelligence change the way people make important decisions?"]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-014', 'S', 'int', 'C', '{"title":"Traditions and change","scenario":"A cultural studies project is collecting students'' views on traditions. You will answer four questions from a researcher.","questions":["Describe a tradition in your family or community that is important to you.","Why do you think some traditions survive for generations while others disappear?","Is it more valuable to preserve traditions or to adapt them to modern life? Explain.","How do you imagine your community will celebrate this tradition fifty years from now?"]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-015', 'S', 'int', 'C', '{"title":"Learning outside the classroom","scenario":"A university committee is studying education reform. You will answer four questions from a committee member.","questions":["Tell me about something important that you learned outside of school.","What are the benefits of learning from experience compared with learning from teachers?","Some employers value practical experience more than university degrees. What is your opinion?","If universities were redesigned from the beginning, what changes would you suggest?"]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-016', 'S', 'int', 'B', '{"title":"Volunteering","scenario":"A university service office is studying student volunteering. You will answer four questions from a coordinator.","questions":["Have you ever done volunteer work? Please describe what you did.","What kinds of volunteer activities do you think are most enjoyable for students?","Some schools require students to complete volunteer hours before they graduate. What do you think of this rule?","How might volunteering change in the future as more people work and study online?"]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-017', 'S', 'int', 'B', '{"title":"Exercise and health","scenario":"A campus health program is collecting information about student fitness. You will answer four questions from a researcher.","questions":["How often do you exercise, and what kind of activity do you usually do?","What makes it easy or difficult for you to stay active during a busy week?","Some universities offer free gym memberships to all students. Do you think this is a good use of money?","If you were designing a program to help students become healthier, what would you include?"]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-018', 'S', 'int', 'B', '{"title":"Travel experiences","scenario":"A tourism research group is asking students about travel. You will answer four questions from an interviewer.","questions":["Tell me about a trip that you remember well.","Do you prefer to travel with friends, with family, or alone? Why?","Some people say that tourism harms the places that people visit. What is your opinion?","How do you think traveling will be different for the next generation?"]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-019', 'S', 'int', 'B', '{"title":"Reading habits","scenario":"A library committee is studying how students read. You will answer four questions from a researcher.","questions":["What kinds of things do you read in your free time?","Do you prefer reading on paper or on a screen, and why?","Some people believe young people read less than they used to. Do you agree?","What changes might happen to books and libraries over the next twenty years?"]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-020', 'S', 'int', 'B', '{"title":"Technology in class","scenario":"A university teaching center is studying technology in classrooms. You will answer four questions from an adviser.","questions":["Which technology do you use most when you study for class?","How does technology help you learn, and when does it make learning harder?","Some teachers ban phones and laptops in their classrooms. Do you think this is a good policy?","If you could add one new technology to every classroom, what would it be and why?"]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-021', 'S', 'int', 'B', '{"title":"Managing money","scenario":"A student services office is surveying students about personal finances. You will answer four questions from a counselor.","questions":["How do you usually decide what to spend your money on?","What do you do when you want to buy something but do not have enough money?","Some people think universities should teach every student how to manage money. What is your view?","How do you think the way people pay for things will change in the future?"]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-022', 'S', 'int', 'B', '{"title":"Housing choices","scenario":"A city housing office is asking students about where they live. You will answer four questions from a researcher.","questions":["Tell me about the place where you live now and what you like about it.","What is the most important thing to consider when choosing a place to live?","Some students prefer living with roommates, while others prefer living alone. Which do you think is better?","If you could design the ideal student neighborhood, what would it include?"]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-B-023', 'S', 'int', 'B', '{"title":"Art and creativity","scenario":"A university is conducting a study on art and creativity. You will answer four questions from a researcher.","questions":["Describe a creative activity that you enjoy or have tried.","How do you feel when you visit a museum or an art exhibition?","Some people say schools should spend more time on art and music. Do you agree or disagree?","How might technology change the way that artists create their work?"]}', NULL, NULL, NULL, 0, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-024', 'S', 'int', 'A', '{"title":"Shopping habits","scenario":"A magazine is writing about how young people shop. You will answer four questions from a reporter.","questions":["Where do you usually buy your clothes?","Tell me about the last thing you bought that you really liked.","Do you think shopping online is better than shopping in a store? Why?","What would you buy if you won a small prize today?"]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-025', 'S', 'int', 'A', '{"title":"Weather and seasons","scenario":"A radio program is asking listeners about the weather. You will answer four questions from the host.","questions":["What is the weather like in your city in the summer?","Which season do you like best, and why do you like it?","Some people feel happier when the weather is sunny. Do you agree?","How would your life be different if you lived in a much colder place?"]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-026', 'S', 'int', 'A', '{"title":"Family and home","scenario":"A student newspaper is writing about family life. You will answer four questions from a student reporter.","questions":["Who do you live with, and what do you like about your home?","What do you usually do together with your family on weekends?","Do you think children should help with the housework? Why or why not?","Describe the home that you would like to have in the future."]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-027', 'S', 'int', 'A', '{"title":"Daily routine","scenario":"A university is doing a survey about student routines. You will answer four questions from a researcher.","questions":["What time do you usually wake up, and what do you do first?","Which part of your day is the busiest for you?","Some people like to plan every day carefully. What do you think about this?","If you could change one thing about your daily routine, what would it be?"]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-028', 'S', 'int', 'A', '{"title":"Holidays and celebrations","scenario":"A community center is collecting stories about holidays. You will answer four questions from an interviewer.","questions":["What is your favorite holiday, and how do you celebrate it?","Tell me about a special meal that you eat on a holiday.","Do you think people spend too much money on celebrations? Why or why not?","How do you think holidays will change in the next twenty years?"]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-029', 'S', 'int', 'C', '{"title":"Technology and privacy","scenario":"A university is researching attitudes toward online privacy. You will answer four questions from a researcher.","questions":["How careful are you about the personal information you share online?","In what ways have apps and websites changed the way people think about privacy?","Some people argue that companies should be forbidden from collecting personal data. To what extent do you agree?","If privacy continues to decline, what consequences might this have for society?"]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-030', 'S', 'int', 'C', '{"title":"Work and careers","scenario":"A career center is studying how students think about their future jobs. You will answer four questions from an advisor.","questions":["What factors are most important to you when you think about a future career?","How has your education influenced the kind of work you would like to do?","Some experts claim that people will change careers several times in their lives. What is your opinion about this?","If many jobs were replaced by automation, how should governments respond?"]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-031', 'S', 'int', 'C', '{"title":"Cities and rural life","scenario":"An urban planning institute is researching where people prefer to live. You will answer four questions from an interviewer.","questions":["Would you rather live in a large city or in the countryside, and why?","How do you think living in a city affects a person''s relationships with others?","Some people believe that rural communities are disappearing. To what degree do you think this is a serious problem?","If you were responsible for improving a city, what changes would you make first?"]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-032', 'S', 'int', 'C', '{"title":"Online learning","scenario":"A university is evaluating its online courses. You will answer four questions from an education researcher.","questions":["What has been your experience with online courses or learning videos?","In what ways does learning online differ from learning in a classroom?","Some educators claim that online courses cannot replace face-to-face teaching. How far do you agree with this view?","If universities offered all of their courses online, what would be gained and what would be lost?"]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-033', 'S', 'int', 'C', '{"title":"Culture and globalization","scenario":"A cultural foundation is researching how global trends affect local traditions. You will answer four questions from an interviewer.","questions":["How are the traditions in your country different from those in other places?","In what ways have foreign films, music, and food influenced the culture where you live?","Some people fear that globalization is destroying local cultures. To what extent is this concern justified?","If you could preserve one tradition for future generations, which would you choose, and why?"]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-034', 'S', 'int', 'A', '{"title":"Pets and animals","scenario":"A pet store is asking customers about animals. You will answer four questions from an interviewer.","questions":["Do you have a pet, or would you like to have one?","Tell me about an animal that you like very much.","Some people think that cats are better pets than dogs. What do you think?","What would you do if you found a lost animal on the street?"]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-035', 'S', 'int', 'A', '{"title":"Music and movies","scenario":"A student club is asking members about their favorite entertainment. You will answer four questions from a club leader.","questions":["What kind of music do you listen to most often?","Tell me about a movie that you watched recently.","Do you prefer watching movies at home or in a theater? Why?","How do you think movies and music will change in the future?"]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-036', 'S', 'int', 'A', '{"title":"Neighborhood","scenario":"A city newspaper is writing about local neighborhoods. You will answer four questions from a reporter.","questions":["What do you like most about the neighborhood where you live?","Where do you usually go to buy food or other things?","Do you think it is important to know your neighbors? Why or why not?","What would you change in your neighborhood if you could?"]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-037', 'S', 'int', 'A', '{"title":"Cooking at home","scenario":"A cooking magazine is asking readers about their meals. You will answer four questions from an editor.","questions":["How often do you cook at home, and what do you usually make?","Tell me about the person who taught you to cook.","Some people think that cooking at home is healthier than eating out. Do you agree?","If you could cook dinner for any guest, who would it be and what would you make?"]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-A-038', 'S', 'int', 'A', '{"title":"Weekend plans","scenario":"A student center is planning weekend activities. You will answer four questions from a staff member.","questions":["What do you usually do on Saturday mornings?","Tell me about a place that you enjoyed visiting on a weekend.","Do you think students should study on weekends? Why or why not?","If you had a free weekend next month, what would you like to do?"]}', NULL, NULL, NULL, -1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-039', 'S', 'int', 'C', '{"title":"Media and news","scenario":"A communications department is researching how people follow the news. You will answer four questions from a researcher.","questions":["How do you usually keep up with news about the world?","In what ways has the internet changed the way people trust information?","Some critics argue that news organizations focus too much on sensational stories. To what extent do you agree?","If people stopped reading the news altogether, what effects might this have on a community?"]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-040', 'S', 'int', 'C', '{"title":"Success and failure","scenario":"A university counseling center is studying attitudes toward failure. You will answer four questions from a counselor.","questions":["How do you usually react when you fail at something important?","In what ways can a failure be useful for a person''s development?","Some people claim that students today are afraid to take risks. How far do you agree with this view?","If schools gave less importance to grades, how might students behave differently?"]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-041', 'S', 'int', 'C', '{"title":"Leadership and teamwork","scenario":"A business school is researching what makes a good team. You will answer four questions from an interviewer.","questions":["Describe a time when you worked as part of a team.","What qualities do you think are most important in a good leader?","Some people believe that the best leaders are born, not made. To what degree do you agree?","If a team member refused to cooperate, how should the group deal with the situation?"]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-042', 'S', 'int', 'C', '{"title":"Science and society","scenario":"A science museum is gathering opinions about research funding. You will answer four questions from an interviewer.","questions":["Which scientific discoveries do you think have most improved daily life?","How should the public be informed about the results of new research?","Some people argue that governments should fund only research with practical benefits. What is your opinion?","If scientists could solve only one global problem in the next decade, which should it be, and why?"]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('S-INT-C-043', 'S', 'int', 'C', '{"title":"Language and identity","scenario":"A university is researching the relationship between language and culture. You will answer four questions from a researcher.","questions":["How important is your first language to your sense of who you are?","In what ways can learning a foreign language change the way a person thinks?","Some linguists claim that speaking several languages makes people more open-minded. To what extent do you agree?","If everyone in the world spoke the same language, how might culture be affected?"]}', NULL, NULL, NULL, 1, 'active', 1793683578909, 1793683578909)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, status = excluded.status, updated_at = excluded.updated_at;
